style.css:
/* ♡ Princess Kitty Dreamland — Tumblr */

/* colors you can swap */
:root {
  --my-pink: #ffb7d5;
  --my-light: #fff0f6;
  --my-dark: #d85d96;
  --my-white: #fffafd;
  --my-lace: #f8d6e5;
  --my-text: #a85d7c;
}

/* dreamy background and text */
html,
body {
  background-color: var(--my-light) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", "Arial", sans-serif !important;
}

/* cute links */
a {
  color: var(--my-dark) !important;
  text-decoration: none !important;
  transition: color .2s ease !important;
}

a:hover {
  color: #ff69aa !important;
  text-decoration: underline wavy !important;
}

/* princess-like images */
img {
  border-radius: 12px !important;
}

/* soft selection */
::selection {
  background: var(--my-pink) !important;
  color: white !important;
}

/* delicate scrollbar */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-light) !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-pink) !important;
  border: 2px solid var(--my-light) !important;
  border-radius: 20px !important;
}
